from collections.abc import Callable, Generator
from typing import Any, TypeVar

from typing_extensions import ParamSpec

from expression.core import Builder, Nothing, Option, Some, option


_TSource = TypeVar("_TSource")
_TResult = TypeVar("_TResult")
_P = ParamSpec("_P")


class OptionBuilder(Builder[_TSource, Option[Any]]):
    def bind(self, xs: Option[_TSource], fn: Callable[[_TSource], Option[_TResult]]) -> Option[_TResult]:
        return option.bind(fn)(xs)

    def return_(self, x: _TSource) -> Option[_TSource]:
        return Some(x)

    def return_from(self, xs: Option[_TSource]) -> Option[_TSource]:
        return xs

    def combine(self, xs: Option[_TSource], ys: Option[_TSource]) -> Option[_TSource]:
        return xs.bind(lambda _: ys)

    def zero(self) -> Option[_TSource]:
        return Nothing

    def __call__(
        self,  # Ignored self parameter
        fn: Callable[
            _P,
            Generator[_TSource | None, _TSource, _TSource | None] | Generator[_TSource | None, None, _TSource | None],
        ],
    ) -> Callable[_P, Option[_TSource]]:
        return super().__call__(fn)


class AsyncOptionBuilder(OptionBuilder[_TSource]):
    """Async version of OptionBuilder for async computations."""

    async def _send(
        self,
        gen: Generator[Any, Any, Any],
        done: list[bool],
        value: _TSource | None = None,
    ) -> Option[_TSource]:
        try:
            # Check if the generator supports send method (i.e. is a true generator)
            # If it doesn't support send, it's likely an iterator (like list_iterator) 
            # that we should handle with next() instead
            try:
                yielded = gen.send(value)
                return self.return_(yielded)
            except AttributeError as ex:
                if "'object' object has no attribute 'send'" in str(ex) or "has no attribute 'send'" in str(ex):
                    # Handle iterators that don't support send (like list_iterator)
                    try:
                        yielded = next(gen)
                        return self.return_(yielded)
                    except StopIteration as stop_ex:
                        done.append(True)
                        # Return of a value in the generator produces StopIteration with a value
                        if stop_ex.value is not None:
                            return self.return_(stop_ex.value)
                        raise
                raise  # Re-raise if it's a different AttributeError
        except StopIteration as ex:
            done.append(True)
            # Return of a value in the generator produces StopIteration with a value
            if ex.value is not None:
                return self.return_(ex.value)
            raise
        except RuntimeError:
            done.append(True)
            raise StopIteration


    def __call__(
        self,  # Ignored self parameter
        fn: Callable[
            _P,
            Generator[_TSource | None, _TSource, _TSource | None] | Generator[_TSource | None, None, _TSource | None],
        ],
    ) -> Callable[_P, Option[_TSource]]:
        """Async option builder."""

        async def async_wrapper(*args: _P.args, **kw: _P.kwargs) -> Option[_TSource]:
            gen = fn(*args, **kw)
            done: list[bool] = []

            result: Option[_TSource] | None = None

            def binder(value: Any) -> Option[_TSource]:
                ret = self._send(gen, done, value)
                # We need to handle the async nature of _send
                return ret

            try:
                result = self._send(gen, done)

                while not done:
                    cont = self.bind(result, binder)

                    # Combine every result except the first
                    if result is None:
                        result = cont
                    else:
                        result = self.combine(result, cont)
            except StopIteration:
                pass

            # If anything returns `None` (i.e raises StopIteration without a value) then
            # we expect the effect to have a zero method implemented.
            if result is None:
                result = self.zero()

            return self.run(result)

        return async_wrapper


__all__ = ["OptionBuilder", "AsyncOptionBuilder"]

